import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.hasNextLine() ? sc.nextLine() : "";

        ArrayList<Integer> values = new ArrayList<>();
        StringBuilder number = new StringBuilder();

        for (char c : input.toCharArray()) {
            if (Character.isDigit(c)) {
                number.append(c);
            } else if (number.length() > 0) {
                values.add(Integer.parseInt(number.toString()));
                number.setLength(0);
            }
        }

        if (number.length() > 0) {
            values.add(Integer.parseInt(number.toString()));
        }

        int k = values.get(values.size() - 1);
        int target = values.get(k);
        int time = 0;

        for (int i = 0; i < values.size() - 1; i++) {
            int count = values.get(i);

            if (i <= k) {
                time += Math.min(count, target);
            } else {
                time += Math.min(count, target - 1);
            }
        }

        System.out.print(time);
    }
}

