import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.hasNextLine() ? sc.nextLine() : "";

        ArrayList<Integer> cards = new ArrayList<>();
        StringBuilder number = new StringBuilder();

        for (char c : input.toCharArray()) {
            if (c == '-' || Character.isDigit(c)) {
                number.append(c);
            } else if (number.length() > 0) {
                cards.add(Integer.parseInt(number.toString()));
                number.setLength(0);
            }
        }

        if (number.length() > 0) {
            cards.add(Integer.parseInt(number.toString()));
        }

        Collections.sort(cards);

        int n = cards.size();
        LinkedList<Integer> deck = new LinkedList<>();

        if (n == 1) {
            deck.add(cards.get(0));
        } else {
            deck.add(cards.get(n - 2));
            deck.addFirst(cards.get(n - 1));

            for (int i = n - 3; i >= 0; i--) {
                deck.addFirst(deck.removeLast());
                deck.addFirst(cards.get(i));
            }
        }

        System.out.print("[");
        for (int i = 0; i < deck.size(); i++) {
            System.out.print(deck.get(i));
            if (i < deck.size() - 1) {
                System.out.print(",");
            }
        }
        System.out.print("]");
    }
}

