import java.util.*;
import java.util.regex.*;

public class Solution {

    static int findStartingPump(int[][] pumps) {
        long totalFuel = 0;
        long currentFuel = 0;
        int start = 0;

        for (int i = 0; i < pumps.length; i++) {
            int fuel = pumps[i][0];
            int cost = pumps[i][1];

            long difference = (long) fuel - cost;

            totalFuel += difference;
            currentFuel += difference;

            if (currentFuel < 0) {
                start = i + 1;
                currentFuel = 0;
            }
        }

        if (totalFuel < 0) {
            return -1;
        }

        return start;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder input = new StringBuilder();

        while (sc.hasNextLine()) {
            input.append(sc.nextLine());
        }

        String data = input.toString().trim();

        Pattern pattern = Pattern.compile("\\[\\s*(-?\\d+)\\s*,\\s*(-?\\d+)\\s*\\]");
        Matcher matcher = pattern.matcher(data);

        List<int[]> list = new ArrayList<>();

        while (matcher.find()) {
            int fuel = Integer.parseInt(matcher.group(1));
            int cost = Integer.parseInt(matcher.group(2));
            list.add(new int[]{fuel, cost});
        }

        if (list.isEmpty()) {
            return;
        }

        int[][] pumps = new int[list.size()][2];

        for (int i = 0; i < list.size(); i++) {
            pumps[i] = list.get(i);
        }

        System.out.println(findStartingPump(pumps));
    }
}

