#define MAX_PUMPS 10000

int main() {
    char input[100000];

    if (fgets(input, sizeof(input), stdin) == NULL) {
        return 0;
    }

    int fuel[MAX_PUMPS];
    int cost[MAX_PUMPS];
    int n = 0;

    char *p = input;

    while (*p != '\0') {
        if (*p == '[') {
            p++;

            char *end;
            int f = (int)strtol(p, &end, 10);
            p = end;

            while (*p != ',' && *p != '\0') {
                p++;
            }

            if (*p == ',') {
                p++;
            }

            int c = (int)strtol(p, &end, 10);
            p = end;

            if (n < MAX_PUMPS) {
                fuel[n] = f;
                cost[n] = c;
                n++;
            }
        } else {
            p++;
        }
    }

    if (n == 0) {
        return 0;
    }

    long long totalFuel = 0;
    long long currentFuel = 0;
    int start = 0;

    for (int i = 0; i < n; i++) {
        long long difference = (long long)fuel[i] - cost[i];

        totalFuel += difference;
        currentFuel += difference;

        if (currentFuel < 0) {
            start = i + 1;
            currentFuel = 0;
        }
    }

    if (totalFuel < 0) {
        printf("-1\n");
    } else {
        printf("%d\n", start);
    }

    return 0;
}

