import java.util.*;
import java.util.regex.*;

public class Solution {

    static int shortestPath(String[] grid, int[] start, int[] goal) {
        int rows = grid.length;
        int cols = grid[0].length();

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{start[0], start[1]});

        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, -1);
        }

        distance[start[0]][start[1]] = 0;

        int[][] directions = {
            {-1, 0},
            {1, 0},
            {0, -1},
            {0, 1}
        };

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            if (r == goal[0] && c == goal[1]) {
                return distance[r][c];
            }

            for (int[] direction : directions) {
                int nr = r + direction[0];
                int nc = c + direction[1];

                while (
                    nr >= 0 &&
                    nr < rows &&
                    nc >= 0 &&
                    nc < cols &&
                    grid[nr].charAt(nc) != 'X'
                ) {
                    if (distance[nr][nc] == -1) {
                        distance[nr][nc] = distance[r][c] + 1;
                        queue.offer(new int[]{nr, nc});
                    }

                    nr += direction[0];
                    nc += direction[1];
                }
            }
        }

        return -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder input = new StringBuilder();

        while (sc.hasNextLine()) {
            input.append(sc.nextLine());
        }

        String data = input.toString();

        Matcher gridMatcher = Pattern.compile(
            "grid=\\[(.*?)\\],\\s*start="
        ).matcher(data);

        if (!gridMatcher.find()) {
            return;
        }

        Matcher rowMatcher = Pattern.compile(
            "\"([^\"]*)\""
        ).matcher(gridMatcher.group(1));

        List<String> gridList = new ArrayList<>();

        while (rowMatcher.find()) {
            gridList.add(rowMatcher.group(1));
        }

        String[] grid = gridList.toArray(new String[0]);

        Matcher startMatcher = Pattern.compile(
            "start=\\((\\d+),\\s*(\\d+)\\)"
        ).matcher(data);

        Matcher goalMatcher = Pattern.compile(
            "goal=\\((\\d+),\\s*(\\d+)\\)"
        ).matcher(data);

        if (!startMatcher.find() || !goalMatcher.find()) {
            return;
        }

        int[] start = {
            Integer.parseInt(startMatcher.group(1)),
            Integer.parseInt(startMatcher.group(2))
        };

        int[] goal = {
            Integer.parseInt(goalMatcher.group(1)),
            Integer.parseInt(goalMatcher.group(2))
        };

        System.out.println(shortestPath(grid, start, goal));
    }
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_ROWS 100
#define MAX_COLS 100

typedef struct {
    int r;
    int c;
} Cell;

Cell queue[MAX_ROWS * MAX_COLS];
int front = 0;
int rear = 0;

void enqueue(int r, int c) {
    queue[rear].r = r;
    queue[rear].c = c;
    rear++;
}

Cell dequeue() {
    return queue[front++];
}

int shortestPath(
    char grid[MAX_ROWS][MAX_COLS],
    int rows,
    int cols,
    int sr,
    int sc,
    int gr,
    int gc
) {
    int distance[MAX_ROWS][MAX_COLS];

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            distance[r][c] = -1;
        }
    }

    front = 0;
    rear = 0;

    enqueue(sr, sc);
    distance[sr][sc] = 0;

    int directions[4][2] = {
        {-1, 0},
        {1, 0},
        {0, -1},
        {0, 1}
    };

    while (front < rear) {
        Cell current = dequeue();
        int r = current.r;
        int c = current.c;

        if (r == gr && c == gc) {
            return distance[r][c];
        }

        for (int d = 0; d < 4; d++) {
            int nr = r + directions[d][0];
            int nc = c + directions[d][1];

            while (
                nr >= 0 &&
                nr < rows &&
                nc >= 0 &&
                nc < cols &&
                grid[nr][nc] != 'X'
            ) {
                if (distance[nr][nc] == -1) {
                    distance[nr][nc] = distance[r][c] + 1;
                    enqueue(nr, nc);
                }

                nr += directions[d][0];
                nc += directions[d][1];
            }
        }
    }

    return -1;
}

int main() {
    char input[10000];

    if (fgets(input, sizeof(input), stdin) == NULL) {
        return 0;
    }

    char grid[MAX_ROWS][MAX_COLS];
    int rows = 0;
    int cols = 0;

    char *gridStart = strstr(input, "grid=[");

    if (gridStart == NULL) {
        return 0;
    }

    gridStart += 6;

    char *p = gridStart;

    while (*p && *p != ']') {
        if (*p == '\"') {
            p++;

            int index = 0;

            while (*p && *p != '\"') {
                grid[rows][index++] = *p;
                p++;
            }

            grid[rows][index] = '\0';
            cols = index;
            rows++;
        }

        if (*p) {
            p++;
        }
    }

    char *startPtr = strstr(input, "start=(");
    char *goalPtr = strstr(input, "goal=(");

    if (startPtr == NULL || goalPtr == NULL) {
        return 0;
    }

    int sr, sc, gr, gc;

    sscanf(startPtr, "start=(%d,%d)", &sr, &sc);
    sscanf(goalPtr, "goal=(%d,%d)", &gr, &gc);

    printf(
        "%d\n",
        shortestPath(grid, rows, cols, sr, sc, gr, gc)
    );

    return 0;
}

