int shortestPath(
    const vector<string>& grid,
    pair<int, int> start,
    pair<int, int> goal
) {
    int rows = grid.size();
    int cols = grid[0].size();

    queue<pair<int, int>> q;
    q.push(start);

    vector<vector<int>> distance(
        rows,
        vector<int>(cols, -1)
    );

    distance[start.first][start.second] = 0;

    vector<pair<int, int>> directions = {
        {-1, 0},
        {1, 0},
        {0, -1},
        {0, 1}
    };

    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();

        if (make_pair(r, c) == goal) {
            return distance[r][c];
        }

        for (auto [dr, dc] : directions) {
            int nr = r + dr;
            int nc = c + dc;

            while (
                nr >= 0 &&
                nr < rows &&
                nc >= 0 &&
                nc < cols &&
                grid[nr][nc] != 'X'
            ) {
                if (distance[nr][nc] == -1) {
                    distance[nr][nc] = distance[r][c] + 1;
                    q.push({nr, nc});
                }

                nr += dr;
                nc += dc;
            }
        }
    }

    return -1;
}

