    vector<string> grid;

    regex gridRegex(R"("([^"]*)")");

    size_t gridStart = input.find("grid=[");
    size_t gridEnd = input.find("], start=");

    if (gridStart == string::npos || gridEnd == string::npos) {
        return 0;
    }

    string gridPart = input.substr(
        gridStart + 6,
        gridEnd - (gridStart + 6)
    );

    for (
        auto it = sregex_iterator(
            gridPart.begin(),
            gridPart.end(),
            gridRegex
        );
        it != sregex_iterator();
        ++it
    ) {
        grid.push_back((*it)[1].str());
    }

    regex startRegex(R"(start=\((\d+),\s*(\d+)\))");
    regex goalRegex(R"(goal=\((\d+),\s*(\d+)\))");

    smatch startMatch;
    smatch goalMatch;

    if (!regex_search(input, startMatch, startRegex) ||
        !regex_search(input, goalMatch, goalRegex)) {
        return 0;
    }

    pair<int, int> start = {
        stoi(startMatch[1].str()),
        stoi(startMatch[2].str())
    };

    pair<int, int> goal = {
        stoi(goalMatch[1].str()),
        stoi(goalMatch[2].str())
    };

    cout << shortestPath(grid, start, goal) << '\n';

    return 0;
}

