        Queue<Integer> q1 = new LinkedList<>();
        Queue<Integer> q2 = new LinkedList<>();

        void push(int x) {
            q2.offer(x);

            while (!q1.isEmpty()) {
                q2.offer(q1.poll());
            }

            Queue<Integer> temp = q1;
            q1 = q2;
            q2 = temp;
        }

        Integer pop() {
            if (!q1.isEmpty()) {
                return q1.poll();
            }
            return null;
        }

        Integer top() {
            if (!q1.isEmpty()) {
                return q1.peek();
            }
            return null;
        }

