class MyCircularQueue {
private:
    vector<int> queue;
    int capacity;
    int front;
    int size;

public:
    MyCircularQueue(int k) {
        queue.resize(k);
        capacity = k;
        front = 0;
        size = 0;
    }

    bool enQueue(int value) {
        if (isFull()) {
            return false;
        }

        int rear = (front + size) % capacity;
        queue[rear] = value;
        size++;

        return true;
    }

    bool deQueue() {
        if (isEmpty()) {
            return false;
        }

        front = (front + 1) % capacity;
        size--;

        return true;
    }

    int Front() {
        if (isEmpty()) {
            return -1;
        }

        return queue[front];
    }

    int Rear() {
        if (isEmpty()) {
            return -1;
        }

        int rear = (front + size - 1) % capacity;
        return queue[rear];
    }

    bool isEmpty() {
        return size == 0;
    }

    bool isFull() {
        return size == capacity;
    }
};

