public class Solution {

    static long maximumRobots(int[] charge, int[] run, long budget) {
        int n = charge.length;
        Deque<Integer> deque = new ArrayDeque<>();

        long runningSum = 0;
        int left = 0;
        int answer = 0;

        for (int right = 0; right < n; right++) {
            runningSum += run[right];

            while (!deque.isEmpty() && charge[deque.peekLast()] <= charge[right]) {
                deque.pollLast();
            }

            deque.offerLast(right);

            while (left <= right) {
                long windowSize = right - left + 1L;
                long totalCost = charge[deque.peekFirst()]
                        + windowSize * runningSum;

                if (totalCost <= budget) {
                    break;
                }

                if (!deque.isEmpty() && deque.peekFirst() == left) {
                    deque.pollFirst();
                }

                runningSum -= run[left];
                left++;
            }

            answer = Math.max(answer, right - left + 1);
        }

        return answer;
    }

