#define MAX_SIZE 10000

typedef struct {
    int data[MAX_SIZE];
    int front;
    int rear;
} Deque;

void pushBack(Deque *dq, int value) {
    dq->data[dq->rear++] = value;
}

void popBack(Deque *dq) {
    if (dq->rear > dq->front) {
        dq->rear--;
    }
}

void popFront(Deque *dq) {
    if (dq->front < dq->rear) {
        dq->front++;
    }
}

int frontValue(Deque *dq) {
    return dq->data[dq->front];
}

int isEmpty(Deque *dq) {
    return dq->front >= dq->rear;
}

int maximumRobots(int charge[], int run[], int n, long long budget) {
    Deque dq = {0, 0};

    long long runningSum = 0;
    int left = 0;
    int answer = 0;

    for (int right = 0; right < n; right++) {
        runningSum += run[right];

        while (!isEmpty(&dq) && charge[dq.data[dq.rear - 1]] <= charge[right]) {
            popBack(&dq);
        }

        pushBack(&dq, right);

        while (left <= right) {
            long long windowSize = right - left + 1LL;
            long long maxCharge = charge[frontValue(&dq)];
            long long totalCost = maxCharge + windowSize * runningSum;

            if (totalCost <= budget) {
                break;
            }

            if (!isEmpty(&dq) && frontValue(&dq) == left) {
                popFront(&dq);
            }

            runningSum -= run[left];
            left++;
        }

        int currentSize = right - left + 1;
        if (currentSize > answer) {
            answer = currentSize;
        }
    }

    return answer;
}

