def max_subarray_sum(nums):
    current = nums[0]
    best = nums[0]

    for i in range(1, len(nums)):
        current = max(nums[i], current + nums[i])
        best = max(best, current)

    return best


def min_subarray_sum(nums):
    current = nums[0]
    best = nums[0]

    for i in range(1, len(nums)):
        current = min(nums[i], current + nums[i])
        best = min(best, current)

    return best


def max_circular_subarray_sum(nums):
    max_sum = max_subarray_sum(nums)

    if max_sum < 0:
        return max_sum

    total_sum = sum(nums)
    min_sum = min_subarray_sum(nums)
    circular_sum = total_sum - min_sum

    return max(max_sum, circular_sum)


