import java.util.*;
import java.util.regex.*;

public class Solution {

    static long maxSubarraySum(int[] nums) {
        long current = nums[0];
        long best = nums[0];

        for (int i = 1; i < nums.length; i++) {
            current = Math.max(nums[i], current + nums[i]);
            best = Math.max(best, current);
        }

        return best;
    }

    static long minSubarraySum(int[] nums) {
        long current = nums[0];
        long best = nums[0];

        for (int i = 1; i < nums.length; i++) {
            current = Math.min(nums[i], current + nums[i]);
            best = Math.min(best, current);
        }

        return best;
    }

    static long maxCircularSubarraySum(int[] nums) {
        long maxSum = maxSubarraySum(nums);

        if (maxSum < 0) {
            return maxSum;
        }

        long totalSum = 0;

        for (int num : nums) {
            totalSum += num;
        }

        long minSum = minSubarraySum(nums);
        long circularSum = totalSum - minSum;

        return Math.max(maxSum, circularSum);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder input = new StringBuilder();

        while (sc.hasNextLine()) {
            input.append(sc.nextLine());
