long long maxSubarraySum(int nums[], int n) {
    long long current = nums[0];
    long long best = nums[0];

    for (int i = 1; i < n; i++) {
        if (current + nums[i] > nums[i]) {
            current = current + nums[i];
        } else {
            current = nums[i];
        }

        if (current > best) {
            best = current;
        }
    }

    return best;
}

long long minSubarraySum(int nums[], int n) {
    long long current = nums[0];
    long long best = nums[0];

    for (int i = 1; i < n; i++) {
        if (current + nums[i] < nums[i]) {
            current = current + nums[i];
        } else {
            current = nums[i];
        }

        if (current < best) {
            best = current;
        }
    }

    return best;
