long long maxCircularSubarraySum(int nums[], int n) {
    long long maxSum = maxSubarraySum(nums, n);

    if (maxSum < 0) {
        return maxSum;
    }

    long long totalSum = 0;

    for (int i = 0; i < n; i++) {
        totalSum += nums[i];
    }

    long long minSum = minSubarraySum(nums, n);
    long long circularSum = totalSum - minSum;

    return maxSum > circularSum ? maxSum : circularSum;
}

