def fill_distances(rooms):
    if not rooms:
        return rooms

    rows = len(rooms)
    cols = len(rooms[0])

    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if rooms[r][c] == 0:
                queue.append((r, c))

    directions = [
        (-1, 0),
        (1, 0),
        (0, -1),
        (0, 1)
    ]

    while queue:
        r, c = queue.popleft()

        for dr, dc in directions:
            nr = r + dr
            nc = c + dc

            if (
                0 <= nr < rows
                and 0 <= nc < cols
                and rooms[nr][nc] == INF
            ):
                rooms[nr][nc] = rooms[r][c] + 1
                queue.append((nr, nc))

    return rooms


