    if not match:
        return []

    content = match.group(1)
    rows = []
    current_row = []
    current_number = ""
    depth = 0

    for char in content:
        if char == '[':
            depth += 1

            if depth == 1:
                current_row = []
                current_number = ""

        elif char == ']':
            if current_number.strip():
                value = current_number.strip()

                if value == "INF":
                    current_row.append(INF)
                else:
                    current_row.append(int(value))

                current_number = ""

            if depth == 1:
                rows.append(current_row)

            depth -= 1

        elif char == ',':
            if depth == 1 and current_number.strip():
                value = current_number.strip()

                if value == "INF":
                    current_row.append(INF)
                else:
                    current_row.append(int(value))

                current_number = ""

        else:
            if depth == 1:
                current_number += char

