import java.util.*;
import java.util.regex.*;

public class Solution {

    static final int INF = 2147483647;

    static void fillDistances(int[][] rooms) {
        if (rooms.length == 0) {
            return;
        }

        int rows = rooms.length;
        int cols = rooms[0].length;

        Queue<int[]> queue = new LinkedList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (rooms[r][c] == 0) {
                    queue.offer(new int[]{r, c});
                }
            }
        }

        int[][] directions = {
            {-1, 0},
            {1, 0},
            {0, -1},
            {0, 1}
        };

        while (!queue.isEmpty()) {
            int[] current = queue.poll();

            int r = current[0];
            int c = current[1];

            for (int[] direction : directions) {
                int nr = r + direction[0];
                int nc = c + direction[1];

                if (
                    nr >= 0 &&
                    nr < rows &&
                    nc >= 0 &&
                    nc < cols &&
                    rooms[nr][nc] == INF
                ) {
                    rooms[nr][nc] = rooms[r][c] + 1;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    static int[][] parseInput(String input) {
        Matcher matcher = Pattern.compile("rooms=\\[(.*)\\]").matcher(input);

        if (!matcher.find()) {
            return new int[0][0];
        }

        String content = matcher.group(1);
        List<int[]> rows = new ArrayList<>();
        List<Integer> currentRow = new ArrayList<>();
        StringBuilder number = new StringBuilder();
        int depth = 0;

        for (int i = 0; i < content.length(); i++) {
            char ch = content.charAt(i);

            if (ch == '[') {
                depth++;
                if (depth == 1) {
                    currentRow = new ArrayList<>();
                    number.setLength(0);
                }
            } else if (ch == ']') {
                if (number.length() > 0) {
                    addValue(currentRow, number.toString());
                    number.setLength(0);
                }

                if (depth == 1) {
                    int[] row = new int[currentRow.size()];
                    for (int j = 0; j < currentRow.size(); j++) {
                        row[j] = currentRow.get(j);
                    }
                    rows.add(row);
                }

                depth--;
            } else if (ch == ',') {
                if (depth == 1 && number.length() > 0) {
                    addValue(currentRow, number.toString());
                    number.setLength(0);
                }
            } else {
                if (depth == 1) {
                    number.append(ch);
                }
            }
        }

        return rows.toArray(new int[0][]);
    }

    static void addValue(List<Integer> row, String value) {
        value = value.trim();

        if (value.equals("INF")) {
            row.add(INF);
        } else {
            row.add(Integer.parseInt(value));
        }
    }

    static String formatOutput(int[][] rooms) {
        StringBuilder result = new StringBuilder("[");

        for (int i = 0; i < rooms.length; i++) {
            if (i > 0) {
                result.append(",");
            }

            result.append("[");

            for (int j = 0; j < rooms[i].length; j++) {
                if (j > 0) {
                    result.append(",");
                }

                if (rooms[i][j] == INF) {
                    result.append("INF");
                } else {
                    result.append(rooms[i][j]);
                }
            }

            result.append("]");
        }

        result.append("]");
        return result.toString();
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        StringBuilder input = new StringBuilder();

        while (scanner.hasNextLine()) {
            input.append(scanner.nextLine());
        }

        int[][] rooms = parseInput(input.toString().trim());
        fillDistances(rooms);

        System.out.println(formatOutput(rooms));
    }
}

