typedef struct {
    int r;
    int c;
} Cell;

Cell queue[MAX_ROWS * MAX_COLS];
int front = 0;
int rear = 0;

void enqueue(int r, int c) {
    queue[rear].r = r;
    queue[rear].c = c;
    rear++;
}

Cell dequeue() {
    return queue[front++];
}

void fillDistances(int rooms[MAX_ROWS][MAX_COLS], int rows, int cols) {
    front = 0;
    rear = 0;

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (rooms[r][c] == 0) {
                enqueue(r, c);
            }
        }
    }

    int directions[4][2] = {
        {-1, 0},
        {1, 0},
        {0, -1},
        {0, 1}
    };

    while (front < rear) {
        Cell current = dequeue();
        int r = current.r;
        int c = current.c;

        for (int d = 0; d < 4; d++) {
            int nr = r + directions[d][0];
            int nc = c + directions[d][1];

            if (
                nr >= 0 &&
                nr < rows &&
                nc >= 0 &&
                nc < cols &&
                rooms[nr][nc] == INF
            ) {
                rooms[nr][nc] = rooms[r][c] + 1;
                enqueue(nr, nc);
            }
        }
    }
}

