        if (ch == '[') {
            depth++;

            if (depth == 1) {
                currentRow.clear();
                number.clear();
            }
        }
        else if (ch == ']') {
            if (!number.empty()) {
                if (number == "INF") {
                    currentRow.push_back(INF);
                } else {
                    currentRow.push_back(stoi(number));
                }

                number.clear();
            }

            if (depth == 1) {
                rooms.push_back(currentRow);
