class PacketQueue:
    def __init__(self):
        self.queue = deque()

    def add_packet(self, packet):
        self.queue.append(packet)

    def process_packet(self):
        if self.queue:
            return self.queue.popleft()
        return -1

    def pending_packets(self):
        return len(self.queue)


def main():
    data = sys.stdin.read().strip()

    if not data:
        return

    router = PacketQueue()
    output = []

    commands = re.findall(
        r'addPacket\(-?\d+\)|processPacket\(\)|pendingPackets\(\)',
        data
    )

    for command in commands:
        if command.startswith("addPacket"):
            packet = int(re.search(r'-?\d+', command).group())
            router.add_packet(packet)

        elif command == "processPacket()":
            output.append(str(router.process_packet()))

        elif command == "pendingPackets()":
            output.append(str(router.pending_packets()))

    print(",".join(output))


