import java.util.*;
import java.util.regex.*;

public class Solution {

    static Queue<Integer> queue = new LinkedList<>();

    static void addPacket(int packet) {
        queue.offer(packet);
    }

    static int processPacket() {
        if (queue.isEmpty()) {
            return -1;
        }
        return queue.poll();
    }

    static int pendingPackets() {
        return queue.size();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder input = new StringBuilder();

        while (sc.hasNextLine()) {
            input.append(sc.nextLine());
        }

        String data = input.toString();

        Pattern pattern = Pattern.compile(
            "addPacket\\(-?\\d+\\)|processPacket\\(\\)|pendingPackets\\(\\)"
        );

        Matcher matcher = pattern.matcher(data);
        List<String> output = new ArrayList<>();

        while (matcher.find()) {
            String command = matcher.group();

            if (command.startsWith("addPacket")) {
                Matcher number = Pattern.compile("-?\\d+").matcher(command);

                if (number.find()) {
                    addPacket(Integer.parseInt(number.group()));
                }
            }
            else if (command.equals("processPacket()")) {
                output.add(String.valueOf(processPacket()));
            }
            else if (command.equals("pendingPackets()")) {
                output.add(String.valueOf(pendingPackets()));
            }
        }

        System.out.println(String.join(",", output));
    }
}

