    packetQueue.push(packet);
}

int processPacket() {
    if (packetQueue.empty()) {
        return -1;
    }

    int packet = packetQueue.front();
    packetQueue.pop();

    return packet;
}

int pendingPackets() {
    return (int)packetQueue.size();
}

