import sys
import re
from collections import deque


class StatisticsTracker:
    def __init__(self):
        self.queue = deque()
        self.total = 0

    def add(self, value):
        self.queue.append(value)
        self.total += value

    def remove(self):
        if self.queue:
            self.total -= self.queue.popleft()

    def get_average(self):
        if not self.queue:
            return 0
        return self.total / len(self.queue)


def format_average(value):
    if value == int(value):
        return str(int(value))
    return str(value)


def main():
    data = sys.stdin.read().strip()

    if not data:
        return

    tracker = StatisticsTracker()
    output = []

    commands = re.findall(
        r'add\(-?\d+(?:\.\d+)?\)|remove\(\)|getAverage\(\)',
        data
    )

    for command in commands:
        if command.startswith("add("):
            value = float(
                re.search(r'-?\d+(?:\.\d+)?', command).group()
            )

            if value.is_integer():
                value = int(value)

            tracker.add(value)

        elif command == "remove()":
            tracker.remove()

        elif command == "getAverage()":
            output.append(format_average(tracker.get_average()))

    print(",".join(output))


if __name__ == "__main__":
    main()

import java.util.*;
import java.util.regex.*;

public class Solution {

    static Queue<Double> queue = new LinkedList<>();
    static double total = 0;

    static void add(double value) {
        queue.offer(value);
        total += value;
    }

    static void remove() {
        if (!queue.isEmpty()) {
            total -= queue.poll();
        }
    }

    static double getAverage() {
        if (queue.isEmpty()) {
            return 0;
        }
        return total / queue.size();
    }

    static String format(double value) {
        if (value == (long) value) {
            return String.valueOf((long) value);
        }
        return String.valueOf(value);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder input = new StringBuilder();

        while (sc.hasNextLine()) {
            input.append(sc.nextLine());
        }

        String data = input.toString();

        Pattern pattern = Pattern.compile(
            "add\\(-?\\d+(?:\\.\\d+)?\\)|remove\\(\\)|getAverage\\(\\)"
        );

        Matcher matcher = pattern.matcher(data);
        List<String> output = new ArrayList<>();

        while (matcher.find()) {
            String command = matcher.group();

            if (command.startsWith("add(")) {
                Matcher number = Pattern.compile(
                    "-?\\d+(?:\\.\\d+)?"
                ).matcher(command);

                if (number.find()) {
                    add(Double.parseDouble(number.group()));
                }
            }
            else if (command.equals("remove()")) {
                remove();
            }
            else if (command.equals("getAverage()")) {
                output.add(format(getAverage()));
            }
        }

        System.out.println(String.join(",", output));
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_QUEUE 10000
#define MAX_INPUT 100000

double queue[MAX_QUEUE];
int front = 0;
int rear = 0;
double total = 0;

void add(double value) {
    if (rear < MAX_QUEUE) {
        queue[rear++] = value;
        total += value;
    }
}

void removeValue() {
    if (front < rear) {
        total -= queue[front++];
    }
}

double getAverage() {
    if (front >= rear) {
        return 0;
    }

    return total / (rear - front);
}

void printNumber(double value) {
    if (value == (long long)value) {
        printf("%lld", (long long)value);
    } else {
        printf("%g", value);
    }
}

int main() {
    char input[MAX_INPUT];

    if (fgets(input, sizeof(input), stdin) == NULL) {
        return 0;
    }

    char *p = input;
    int firstOutput = 1;

    while (*p != '\0') {
        if (strncmp(p, "add(", 4) == 0) {
            p += 4;

            char *end;
            double value = strtod(p, &end);

            add(value);
            p = end;

            if (*p == ')') {
                p++;
            }
        }
        else if (strncmp(p, "remove()", 8) == 0) {
            removeValue();
            p += 8;
        }
        else if (strncmp(p, "getAverage()", 12) == 0) {
            if (!firstOutput) {
                printf(",");
            }

            printNumber(getAverage());
            firstOutput = 0;
            p += 12;
        }
        else {
            p++;
        }
    }

    printf("\n");
    return 0;
}

